84|<script>
85|import * as echarts from 'echarts';
86|
87|export default {
88|  name: 'FootballGoalsChart',
89|  data() {
90|    return {
91|      selectedYear: 2024,
92|      selectedTeam: 'china',
93|      chartType: 'bar',
94|      yearOptions: [2022, 2023, 2024],
95|      teamOptions: [
96|        { label: '中国国家队', value: 'china' },
97|        { label: '中国U23', value: 'china_u23' },
98|        { label: '中国女足', value: 'china_women' }
99|      ],
100|      goalsData: [],
101|      chartInstance: null,
102|      totalGoals: 0,
103|      averageGoals: 0,
104|      maxMonth: '',
105|      maxGoals: 0,
106|      minMonth: '',
107|      minGoals: 0,
108|      trendText: '较去年上升',
109|      trendClass: 'trend-up'
110|    };
111|  },
112|  mounted() {
113|    this.initChart();
114|    this.loadMockData();
115|  },
116|  beforeDestroy() {
117|    if (this.chartInstance) {
118|      this.chartInstance.dispose();
119|    }
120|  },
121|  methods: {
122|    initChart() {
123|      this.chartInstance = echarts.init(this.$refs.goalsChart);
124|      window.addEventListener('resize', this.handleResize);
125|    },
126|    loadMockData() {
127|      // Mock 数据：2024年中国国家队每月进球数
128|      this.goalsData = [
129|        { month: '1月', goals: 5 },
130|        { month: '2月', goals: 8 },
131|        { month: '3月', goals: 12 },
132|        { month: '4月', goals: 7 },
133|        { month: '5月', goals: 15 },
134|        { month: '6月', goals: 10 },
135|        { month: '7月', goals: 9 },
136|        { month: '8月', goals: 14 },
137|        { month: '9月', goals: 11 },
138|        { month: '10月', goals: 13 },
139|        { month: '11月', goals: 6 },
140|        { month: '12月', goals: 8 }
141|      ];
142|      this.calculateSummary();
143|      this.renderChart();
144|    },
145|    calculateSummary() {
146|      // 计算总进球数
147|      this.totalGoals = this.goalsData.reduce((sum, item) => sum + item.goals, 0);
148|      
149|      // 计算平均每月进球
150|      this.averageGoals = (this.totalGoals / this.goalsData.length).toFixed(1);
151|      
152|      // 找出最高和最低进球月份
153|      let maxItem = this.goalsData[0];
154|      let minItem = this.goalsData[0];
155|      
156|      this.goalsData.forEach(item => {
157|        if (item.goals > maxItem.goals) {
158|          maxItem = item;
159|        }
160|        if (item.goals < minItem.goals) {
161|          minItem = item;
162|        }
163|      });
164|      
165|      this.maxMonth = maxItem.month;
166|      this.maxGoals = maxItem.goals;
167|      this.minMonth = minItem.month;
168|      this.minGoals = minItem.goals;
169|      
170|      // 模拟趋势数据
171|      this.trendText = this.totalGoals > 100 ? '较去年上升' : '较去年下降';
172|      this.trendClass = this.totalGoals > 100 ? 'trend-up' : 'trend-down';
173|    },
174|    renderChart() {
175|      if (!this.chartInstance) return;
176|      
177|      const months = this.goalsData.map(item => item.month);
178|      const goals = this.goalsData.map(item => item.goals);
179|      
180|      let seriesConfig = {};
181|      
182|      if (this.chartType === 'pie') {
183|        seriesConfig = {
184|          type: 'pie',
185|          radius: '50%',
186|          data: this.goalsData.map(item => ({
187|            name: item.month,
188|            value: item.goals
189|          })),
190|          emphasis: {
191|            itemStyle: {
192|              shadowBlur: 10,
193|              shadowOffsetX: 0,
194|              shadowColor: 'rgba(0, 0, 0, 0.5)'
195|            }
196|          }
197|        };
198|      } else {
199|        seriesConfig = {
200|          type: this.chartType,
201|          data: goals,
202|          itemStyle: {
203|            color: '#409EFF'
204|          },
205|          barWidth: '60%',
206|          lineStyle: {
207|            width: 3
208|          }
209|        };
210|      }
211|      
212|      const option = {
213|        title: {
214|          text: `${this.selectedYear}年中国足球每月进球统计`,
215|          left: 'center',
216|          textStyle: {
217|            fontSize: 18,
218|            fontWeight: 'bold'
219|          }
220|        },
221|        tooltip: {
222|          trigger: 'axis',
223|          formatter: this.chartType === 'pie' ? '{b}: {c}球 ({d}%)' : '{b}<br/>{a}: {c}球'
224|        },
225|        legend: {
226|          show: this.chartType === 'pie',
227|          orient: 'vertical',
228|          left: 'left'
229|        },
230|        grid: {
231|          left: '3%',
232|          right: '4%',
233|          bottom: '3%',
234|          containLabel: true
235|        },
236|        xAxis: {
237|          type: 'category',
238|          data: months,
239|          axisLabel: {
240|            rotate: 45
241|          }
242|        },
243|        yAxis: {
244|          type: 'value',
245|          name: '进球数',
246|          nameTextStyle: {
247|            padding: [0, 0, 0, 10]
248|          }
249|        },
250|        series: [{
251|          name: '进球数',
252|          ...seriesConfig
253|        }]
254|      };
255|      
256|      if (this.chartType === 'pie') {
257|        delete option.xAxis;
258|        delete option.yAxis;
259|        delete option.grid;
260|      }
261|      
262|      this.chartInstance.setOption(option);
263|      this.chartInstance.resize();
264|    },
265|    handleYearChange() {
266|      // 模拟不同年份数据加载
267|      this.loadMockData();
268|    },
269|    handleTeamChange() {
270|      // 模拟不同球队数据加载
271|      this.loadMockData();
272|    },
273|    handleChartTypeChange() {
274|      this.renderChart();
275|    },
276|    refreshChart() {
277|      this.$message({
278|        message: '数据已刷新',
279|        type: 'success',
280|        duration: 1500
281|      });
282|      this.loadMockData();
283|    },
284|    downloadChart() {
285|      if (this.chartInstance) {
286|        const chartData = this.chartInstance.getDataURL({
287|          type: 'png',
288|          pixelRatio: 2,
289|          backgroundColor: '#fff'
290|        });
291|        
292|        const link = document.createElement('a');
293|        link.href = chartData;
294|        link.download = `足球进球统计_${this.selectedYear}_${this.selectedTeam}.png`;
295|        link.click();
296|        
297|        this.$message({
298|          message: '图表已导出',
299|          type: 'success',
300|          duration: 1500
301|        });
302|      }
303|    },
304|    handleResize() {
305|      if (this.chartInstance) {
306|        this.chartInstance.resize();
307|      }
308|    }
309|  }
310|};
311|</script>
