I'll verify the River City Ransom character drawing improvements. Let me start by examining the code and then testing it.

### Check: Read the modified file and understand the changes
**Command run:**
```bash
cd /Users/shiyun/workspace/AIFront && git diff HEAD -- src/views/RiverCityRansom.vue | head -200
```
**Output observed:**
```
diff --git a/src/views/RiverCityRansom.vue b/src/views/RiverCityRansom.vue
index 8b1f2a3..c4d5e6f 100644
--- a/src/views/RiverCityRansom.vue
+++ b/src/views/RiverCityRansom.vue
@@ -1,5 +1,5 @@
 <template>
-  <div class="river-city-ransom">
+  <div class="river-city-ransom" id="river-city-root">
     <h1>热血物语</h1>
     <div class="game-container">
       <canvas id="gameCanvas" width="800" height="600"></canvas>
@@ -45,7 +45,7 @@
       <button @click="startGame">开始游戏</button>
       <button @click="resetGame">重置</button>
     </div>
   </div>
 </template>

 <script>
 export default {
   name: 'RiverCityRansom',
   data() {
     return {
       gameStarted: false,
       player: {
         x: 100,
         y: 400,
         width: 40,
         height: 60,
         speed: 5,
         direction: 'right',
         moving: false,
         legPhase: 0
       },
       keys: {},
       canvas: null,
       ctx: null,
       animationId: null,
       gameLoopRunning: false
     }
   },
   mounted() {
     this.canvas = this.$refs.gameCanvas
     this.ctx = this.canvas.getContext('2d')
     this.drawCharacter()
     this.setupKeyboard()
   },
   methods: {
     setupKeyboard() {
       window.addEventListener('keydown', this.handleKeyDown)
       window.addEventListener('keyup', this.handleKeyUp)
     },
     handleKeyDown(e) {
       this.keys[e.key] = true
       if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
         this.player.moving = true
       }
     },
     handleKeyUp(e) {
       this.keys[e.key] = false
       if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') {
         this.player.moving = false
       }
     },
     startGame() {
       this.gameStarted = true
       this.startGameLoop()
     },
     resetGame() {
       this.gameStarted = false
       this.stopGameLoop()
       this.player.x = 100
       this.player.y = 400
       this.player.moving = false
       this.drawCharacter()
     },
     startGameLoop() {
       if (this.gameLoopRunning) return
       this.gameLoopRunning = true
       const loop = () => {
         if (!this.gameStarted) return
         if (this.keys['ArrowRight']) {
           this.player.x += this.player.speed
           this.player.direction = 'right'
           this.player.moving = true
         }
         if (this.keys['ArrowLeft']) {
           this.player.x -= this.player.speed
           this.player.direction = 'left'
           this.player.moving = true
         }
         if (this.player.moving) {
           this.player.legPhase += 0.3
         }
         this.drawCharacter()
         this.animationId = requestAnimationFrame(loop)
       }
       this.animationId = requestAnimationFrame(loop)
     },
     stopGameLoop() {
       this.gameLoopRunning = false
       if (this.animationId) {
         cancelAnimationFrame(this.animationId)
         this.animationId = null
       }
     },
     drawCharacter() {
       const ctx = this.ctx
       const p = this.player
       ctx.clearRect(0, 0, 800, 600)

       // Draw ground
       ctx.fillStyle = '#8B7355'
       ctx.fillRect(0, 500, 800, 100)

       // Draw character
       const x = p.x
       const y = p.y

       // Legs with swing animation
       const legSwing = Math.sin(p.legPhase) * 7  // Increased from 4 to 7
       const legSwing2 = Math.sin(p.legPhase + Math.PI) * 7

       // Draw legs (dark pants)
       ctx.strokeStyle = '#2F4F4F'
       ctx.lineWidth = 4
       ctx.beginPath()
       ctx.moveTo(x, y + 40)
       ctx.lineTo(x + legSwing, y + 55)
       ctx.stroke()

       ctx.beginPath()
       ctx.moveTo(x, y + 40)
       ctx.lineTo(x + legSwing2, y + 55)
       ctx.stroke()

       // Draw shoes
       ctx.fillStyle = '#1a1a1a'
       ctx.fillRect(x + legSwing - 3, y + 53, 10, 5)
       ctx.fillRect(x + legSwing2 - 3, y + 53, 10, 5)

       // Draw body (dark school uniform)
       ctx.fillStyle = '#2F4F4F'
       ctx.fillRect(x - 10, y + 15, 20, 30)

